function currentPosition(){if(transport?.practice)return playbackPosition(transport,audio.ctx.currentTime);if(transport){const raw=(audio.ctx.currentTime-transport.start)/transport.sec;return {beat:Math.max(0,raw%totalBeats(transport.project)),counting:raw<0,remaining:Math.ceil(-raw),tempo:p.bpm,pass:1}}return {beat:playCursor,counting:false,tempo:p.bpm,pass:1}}
