function seekTo(beat){const was=!!transport&&!transport.recording;stop();const project=playbackProject();playCursor=Math.max(0,Math.min(Number(beat)||0,totalBeats(project)-.25));refreshPractice();if(view==='my-part')renderPartView();if(was)startPlayback();}
function applyListeningMix(){if(!transport?.practice)return;const tr=transport;for(const t of tr.project.tracks){const live=p.tracks.find(x=>x.id===t.id);if(live)Object.assign(t,{volume:live.volume,pan:live.pan,reverbSend:live.reverbSend,muted:live.muted,solo:live.solo})}tr.audible=new Set(listeningTracks(tr.project,tr.listen,tr.part).map(t=>t.id));const mix={...p,tracks:tr.project.tracks.map(t=>({...t,muted:!tr.audible.has(t.id),solo:false}))};audio.applyMix(mix);}
