function artwork(i,{playing=false}={}){const a=ART[i.id];if(!a)return `<div class="loading-art">${esc(i.name)}</div>`;const w=a.width||1536,h=a.height||1024,ns=playing?trackNotes():[];let hit='';if(playing){hit=(a.hits||[]).map((s,slot)=>{const index=s.noteIndex??slot,n=ns[index]||ns[0];if(!n)return '';const cls='hit '+(!n.enabled?'removed':'');let shape;if(s.ellipse){const [x,y,rx,ry]=s.ellipse;shape=`<ellipse cx="${x*w}" cy="${y*h}" rx="${rx*w}" ry="${ry*h}"`}else if(s.rect){const [x,y,b,c]=s.rect;shape=`<rect x="${x*w}" y="${y*h}" width="${b*w}" height="${c*h}"`}else{shape=`<polygon points="${(s.points||[]).map(([x,y])=>x*w+','+y*h).join(' ')}"`};let pos=s.label;if(!pos){if(s.ellipse)pos=s.ellipse.slice(0,2);else if(s.rect)pos=[s.rect[0]+s.rect[2]/2,s.rect[1]+s.rect[3]/2];else if(s.points?.length)pos=[s.points.reduce((v,a)=>v+a[0],0)/s.points.length,s.points.reduce((v,a)=>v+a[1],0)/s.points.length];}const text=solfege&&isBarred(i)?['do','re','mi','fa','so','la','ti','do','re','mi','fa','so','la'][index]:n.label;return shape+` class="${cls}" data-hit="${index}" role="button" tabindex="0" aria-label="Play ${esc(n.label)}"/>`+(labels&&pos?`<text class="bar-label" style="font-size:${w*.023}px;stroke-width:${w*.003}px" x="${pos[0]*w}" y="${pos[1]*h}" text-anchor="middle" dominant-baseline="middle">${esc(text)}</text>`:'');}).join('');}
 const vb=a.viewBox||[0,0,w,h];return `<svg viewBox="${vb.join(' ')}" role="group" aria-label="${esc(i.name)}" preserveAspectRatio="xMidYMid meet"><image class="instrument-photo" href="${a.src}" width="${w}" height="${h}"/>${hit}</svg>`}
