function sequenceCellClick(button,input){
 const t=activeTrack();if(!t)return;
 const [index,col]=button.dataset.cell.split(',').map(Number),n=notesFor(getInstrument(t.instrument),p.key)[index];
 const id=button.dataset.note,existing=t.events.find(e=>e.id===id);
 if(sequenceTool==='erase'||input.shiftKey){
  if(existing)mutate(()=>{t.events=t.events.filter(e=>e.id!==existing.id);if(selectedEvent===existing.id)selectedEvent=null;});
  return;
 }
 if(sequenceTool==='select'||button.dataset.event){selectedEvent=existing?.id||null;renderSequence();return;}
 const beat=col*grid;
 mutate(()=>{const event={id:uid(),beat,duration:Math.min(duration,totalBeats(p)-beat),note:n.note,shift:n.shift||0,velocity};t.events.push(event);selectedEvent=event.id;});
 audio.load(getInstrument(t.instrument),n.note,n.shift||0).then(()=>{audio.applyMix(p);audio.play(getInstrument(t.instrument),{...n,velocity,duration},t);}).catch(err=>toast(err.message));
}


async function start(record=false){
 if(!record)return startPlayback();if(busy)return;if(transport)stop();
 const request=++playbackRequest;busy=true;let arm;
 try{
  playScope='section';syncTransport();if(!ensureTrack())return;checkpoint();syncSection(p);
  const playing=p;arm={project:playing,sectionId:p.activeSection,scope:'section',start:null,recording:true,recorded:new Map(),pending:[],timer:null};recordingArm=arm;
  updateTakeButton();$('#transport-state').textContent='PREPARING RECORDING';$('#record').classList.add('recording');
  await audio.prepareProject(playing);if(request!==playbackRequest)return;
  await audio.prepareInstrument(getInstrument(instrument),p.key);if(request!==playbackRequest)return;readyInstrument=instrument;updateReady('READY TO PLAY');
  const sec=60/p.bpm,count=countIn?barBeats(p):0;
  Object.assign(arm,{start:audio.ctx.currentTime+.12+count*sec,sec,from:audio.ctx.currentTime,nextClick:-count});
  transport=arm;recordingArm=null;
  if(flushRecording(arm)){save();renderSidebar();refreshMidiPart();updateTakeButton();}
  transport.timer=setInterval(schedule,25);$('#play').textContent='Ⅱ';$('#play').classList.add('playing');schedule();raf=requestAnimationFrame(tick);
 }catch(e){toast(e.message);stop();}finally{if(recordingArm===arm)recordingArm=null;busy=false;}
}
function schedule(){if(transport?.practice)return schedulePlayback();if(!transport)return;const tr=transport,playing=tr.project,now=audio.ctx.currentTime,horizon=now+.12,total=totalBeats(playing),cycleSeconds=total*tr.sec,first=Math.max(0,Math.floor((tr.from-tr.start)/cycleSeconds)),last=Math.max(0,Math.floor((horizon-tr.start)/cycleSeconds));for(let cycle=first;cycle<=last;cycle++){if(!p.loop&&cycle>0)break;for(const t of playing.tracks){const live=p.tracks.find(x=>x.id===t.id);if(live)Object.assign(t,{volume:live.volume,pan:live.pan,reverbSend:live.reverbSend,muted:live.muted,solo:live.solo});}for(const t of audibleTracks(playing)){const inst=getInstrument(t.instrument);for(const e of t.events){const at=tr.start+(cycle*total+e.beat)*tr.sec;if(at>=tr.from&&at<horizon&&tr.recorded.get(e.id)!==cycle&&![...recorderHolds.values(),...midiHolds.values()].some(h=>h.event?.id===e.id)){audio.play(inst,e,t,at);const ns=notesFor(inst,playing.key),ix=ns.findIndex(n=>n.note===e.note&&(n.shift||0)===(e.shift||0));const handle=setTimeout(()=>{flash(inst.id,ix,inst.shape==='recorder'?e.duration*tr.sec:.16,t.id);notesTimeouts.delete(handle)},Math.max(0,(at-now)*1000));notesTimeouts.add(handle);}}}}
 const clickStep=playing.meter==='6/8'?.5:1;while(tr.start+tr.nextClick*tr.sec<horizon){const at=tr.start+tr.nextClick*tr.sec;if((tr.nextClick<0||metro)&&at>=now-.005&&(p.loop||tr.nextClick<total))audio.click(Math.max(at,now),Math.abs(tr.nextClick%(playing.meter==='6/8'?1.5:barBeats(playing)))<.001,metroVolume);tr.nextClick+=clickStep;}tr.from=horizon;
 if(!p.loop&&now>=tr.start+cycleSeconds){stop(false);toast('Playback finished.')}}
function tick(){if(!transport)return;updateMusicalContext();const tr=transport,playing=tr.project,pos=currentPosition(),beat=pos.counting?-pos.remaining:pos.beat,total=totalBeats(playing),b=Math.max(0,pos.beat),bar=Math.floor(b/barBeats(playing))+1,beatIn=Math.floor((b%barBeats(playing))*(playing.meter==='6/8'?2:1))+1;$('#position').innerHTML=String(bar).padStart(2,'0')+' <span>·</span> '+String(beatIn).padStart(2,'0');const marker=playing.sectionMarkers?.findLast(m=>m.beat<=b);$$('[data-entry]').forEach(el=>el.classList.toggle('is-playing',tr.scope==='song'&&el.dataset.entry===marker?.entryId));$('#transport-state').textContent=beat<0?'COUNT IN · '+Math.ceil(-beat):tr.recording?'RECORDING':tr.scope==='song'?'SONG · '+(marker?.name||''):'LOOP';const local=tr.scope==='song'&&marker?b-marker.beat:b,show=tr.scope==='section'||marker?.sectionId===p.activeSection;const head=$('.playhead');if(head){head.hidden=!show;head.style.left=local/totalBeats(p)*100+'%'}const seq=$('.sequence-playhead');if(seq){seq.hidden=!show;seq.style.left=`calc(80px + (100% - 80px) * ${local/totalBeats(p)})`}updatePracticeBar($('#rehearsal-dock'),pos,playing);raf=requestAnimationFrame(tick)}
function stop(cut=true){playbackRequest++;if(recordingArm)recordingArm.pending=[];recordingArm=null;releaseRecorderNotes();if(transport){if(transport.practice)playCursor=currentPosition().beat;clearInterval(transport.timer);const recorded=transport.recording;if(recorded)rememberTake(p,transport);transport=null;if(recorded){changed();if(view==='sequence'||view==='score')renderView()}}cancelAnimationFrame(raf);for(const t of notesTimeouts)clearTimeout(t);notesTimeouts.clear();if(cut)audio.stop();audio.applyMix(p);$$('.struck').forEach(el=>el.classList.remove('struck'));$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play from current position');$('#play').classList.remove('playing');$('#record').classList.remove('recording');$('#transport-state').textContent='READY TO PLAY';$('#position').innerHTML=String(Math.floor(playCursor/barBeats(p))+1).padStart(2,'0')+' <span>·</span> 01';updatePracticeBar($('#rehearsal-dock'),{beat:playCursor,counting:false,tempo:p.bpm*practiceSettings(p.rehearsal,p.bars).speed,pass:1},practicePreview||p);$$('.playhead,.sequence-playhead').forEach(el=>el.hidden=true);$$('.is-playing').forEach(el=>el.classList.remove('is-playing'));updateMusicalContext();updateTakeButton();}
