  if(exportingWav)return;
  exportingWav=true;button.disabled=true;button.textContent='Preparing WAV…';status.textContent='Rendering your loop and its final sound decay…';$('#export-wav-button').disabled=true;
  try{const blob=await exportLoopWav(audio,snapshot);if(!button.isConnected||!$('#modal').open)return;wavUrl=URL.createObjectURL(blob);saveLink.href=wavUrl;saveLink.download=name;saveLink.hidden=false;button.hidden=true;preview.src=wavUrl;preview.hidden=false;status.textContent='Your WAV is ready ('+(blob.size/1048576).toFixed(1)+' MB). Download it below, or listen first.';saveLink.focus();}
