$('#project-title').onchange=e=>mutate(()=>p.title=e.target.value.trim()||'Untitled session');$('#project-menu-button').onclick=projectMenu;$('#export-wav-button').onclick=wavExportDialog;$('#compare-button').onclick=()=>{stop();showWelcome()};$('#help-button').onclick=help;$('#play-scope').onchange=e=>{stop();playScope=e.target.value;playCursor=0;p.playbackScope=playScope;save();renderView()};$('#play').onclick=()=>start(false);$('#record').onclick=()=>transport?.recording||recordingArm?stop():start(true);$('#stop').onclick=()=>stop();$('#rewind').onclick=()=>seekTo(0);$('#loop').onclick=()=>{p.loop=!p.loop;if(transport?.practice)transport.repeat=transport.settings.enabled||p.loop;changed()};$('#metronome').onclick=()=>{metro=!metro;$('#metronome').classList.toggle('active',metro);$('#metronome').setAttribute('aria-pressed',metro)};$('#metronome').ondblclick=recordSettings;$('#master').onpointerdown=()=>checkpoint();$('#master').oninput=e=>{p.master=+e.target.value;changed()};for(const id of ['bpm','meter','bars'])$('#'+id).onchange=e=>{const value=id==='meter'?e.target.value:+e.target.value;if(id==='bpm'&&(!Number.isFinite(value)||value<30||value>240)||id==='bars'&&(!Number.isInteger(value)||value<1||value>4)){syncTransport();return}if(id==='bars'){changeSectionLength(value);return;}stop();mutate(()=>{p[id]=value;trimSections(p)})};$('#undo-button').onclick=()=>undoAction();$('#redo-button').onclick=()=>undoAction(true);$('#fullscreen-button').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen()}catch{toast('Open the studio in its own browser tab to use full screen.')}};
$('#open-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>15000000){toast('This project is too large to open.');return}try{const loaded=validateProject(JSON.parse(await f.text()));stop();closeModal();mutate(()=>{p=ensureSong(loaded);playCursor=0;practicePart=null;playScope='section';outputScope=playScope;if(playScope==='song')view='song';trackId=p.tracks[0]?.id;instrument=p.tracks[0]?.instrument||'alto-xylophone';selectedEvent=null});if(playScope==='song')setView('song');toast('Project opened.')}catch(err){toast(err.message)}finally{e.target.value=''}};
document.addEventListener('keydown',e=>{if(e.target.matches?.('input,select,textarea')||$('#modal').open||$('#welcome').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undoAction(e.shiftKey);return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();undoAction(true);return}if(view==='score'&&(e.ctrlKey||e.metaKey)&&scoreController?.handleKey(e))return;if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.target.closest?.('button,summary')&&(e.key===' '||e.key==='Enter'))return;if(view==='score'&&scoreController?.handleKey(e))return;if(e.key==='Escape'){stop();return}if(e.key===' '){e.preventDefault();if(!e.repeat)start();return}if(e.key.toLowerCase()==='r'){e.preventDefault();if(!e.repeat)transport?.recording||recordingArm?stop():start(true);return}if(view==='instrument'&&!e.repeat){if(getInstrument(instrument)?.shape==='recorder'){const index=RECORDER_KEYS.indexOf(e.key.toLowerCase());if(index>=0){e.preventDefault();beginRecorderNote(index+recorderOctave*12,'key-'+e.code,e.timeStamp)}}else{const index=KEYS.indexOf(e.key.toLowerCase());if(index>=0){e.preventDefault();pressed.add(e.code);playNote(index,e.timeStamp)}}}});document.addEventListener('keyup',e=>{pressed.delete(e.code);releaseRecorderNote('key-'+e.code,e.timeStamp)});window.addEventListener('blur',()=>{midiSuspended=true;pressed.clear();releaseRecorderNotes()});window.addEventListener('focus',()=>{midiSuspended=false});document.addEventListener('visibilitychange',()=>{if(document.hidden){releaseRecorderNotes();flushSave(false)}});window.addEventListener('pagehide',()=>flushSave(false));window.addEventListener('beforeunload',e=>{releaseRecorderNotes();if(!flushSave(false)&&JSON.stringify(p)!==lastDownloadSnapshot){e.preventDefault();e.returnValue=''}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
syncTransport();renderSidebar();renderView();updateHistory();

const showWelcome=initWelcome();
